import{_ as t,o,c as a,ag as s}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/slides/add-content-shape-picker.png",l="/docs/images/slides/add-content-insert-sheet-mobile.png",m=JSON.parse('{"title":"Add content","description":"Add and manage slides, then fill them with text, images, shapes, tables, and connector lines.","frontmatter":{"title":"Add content","description":"Add and manage slides, then fill them with text, images, shapes, tables, and connector lines.","type":"how-to"},"headers":[],"relativePath":"slides/add-content.md","filePath":"slides/add-content.md"}'),r={name:"slides/add-content.md"};function i(d,e,h,c,g,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="add-content" tabindex="-1">Add content <a class="header-anchor" href="#add-content" aria-label="Permalink to &quot;Add content&quot;">​</a></h1><p>Add slides to a deck and fill them with text, images, shapes, tables, and lines that connect shapes.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. A share-link viewer can page through the deck but can&#39;t change it.</li><li>Most tasks work on a phone; see <a href="#on-a-phone">On a phone</a> for where the controls are.</li></ul></div><h2 id="add-a-slide" tabindex="-1">Add a slide <a class="header-anchor" href="#add-a-slide" aria-label="Permalink to &quot;Add a slide&quot;">​</a></h2><ol><li>Open the presentation.</li><li>Click <strong>Add slide</strong> (the + button) in the toolbar. A blank slide opens after the current one.</li></ol><p>To pick the layout as you add it, click the arrow next to <strong>Add slide</strong> (tooltip <strong>Choose a layout</strong>) and select a layout. To add a slide with the same layout as the current one, press <code>⌘+M</code> / <code>Ctrl+M</code>.</p><p>You can also right-click a thumbnail in the slide strip and select <strong>New slide</strong>.</p><h2 id="duplicate-delete-or-reorder-slides" tabindex="-1">Duplicate, delete, or reorder slides <a class="header-anchor" href="#duplicate-delete-or-reorder-slides" aria-label="Permalink to &quot;Duplicate, delete, or reorder slides&quot;">​</a></h2><ol><li>In the slide strip, click a slide. To pick several, hold <code>Shift</code> and click each one.</li><li>Right-click one of the selected slides.</li><li>Select <strong>Duplicate slide</strong> or <strong>Delete slide</strong>. With several slides selected, the items read <strong>Duplicate 3 slides</strong> or <strong>Delete 3 slides</strong>.</li></ol><p>To reorder, drag a thumbnail up or down the strip. To duplicate the current slide from the keyboard, press <code>⌘+Shift+D</code> / <code>Ctrl+Shift+D</code>.</p><p>A deck always keeps at least one slide, so you can&#39;t delete every slide.</p><h2 id="change-a-slide-s-layout" tabindex="-1">Change a slide&#39;s layout <a class="header-anchor" href="#change-a-slide-s-layout" aria-label="Permalink to &quot;Change a slide&#39;s layout&quot;">​</a></h2><ol><li>Right-click the slide&#39;s thumbnail, or an empty part of the slide.</li><li>Select <strong>Change layout…</strong> and pick a layout.</li></ol><p>Text you already typed moves into the matching place on the new layout: the title stays a title and body text stays in the body. See <a href="/docs/slides/themes-and-layouts.html#built-in-layouts">Themes and layouts</a> for the list.</p><h2 id="type-in-a-placeholder" tabindex="-1">Type in a placeholder <a class="header-anchor" href="#type-in-a-placeholder" aria-label="Permalink to &quot;Type in a placeholder&quot;">​</a></h2><ol><li>Click a placeholder such as <strong>Click to add title</strong> or <strong>Click to add text</strong>.</li><li>Type your text.</li><li>Press <code>Escape</code> or click <strong>Done</strong> at the end of the toolbar.</li></ol><p>To edit text that is already there, double-click it. You can also select a text box or shape and start typing, or press <code>Enter</code> or <code>F2</code>.</p><h2 id="add-a-text-box" tabindex="-1">Add a text box <a class="header-anchor" href="#add-a-text-box" aria-label="Permalink to &quot;Add a text box&quot;">​</a></h2><ol><li>Click <strong>Text box</strong> (the T icon) in the toolbar.</li><li>Click the slide to place a box at the default size, or drag to draw the box you want.</li><li>Type your text.</li></ol><h2 id="format-text" tabindex="-1">Format text <a class="header-anchor" href="#format-text" aria-label="Permalink to &quot;Format text&quot;">​</a></h2><ol><li>Double-click the text to edit it, then select the words you want to change.</li><li>Use the toolbar controls:</li></ol><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Font</strong> and <strong>Font size</strong></td><td>Change the typeface and size. Use − and + to step the size.</td></tr><tr><td><strong>Bold</strong>, <strong>Italic</strong>, <strong>Underline</strong></td><td>Style the selected text.</td></tr><tr><td><strong>Text color</strong></td><td>Change the text color.</td></tr><tr><td><strong>Insert link</strong> / <strong>Remove link</strong></td><td>Turn the selection into a link, or remove one.</td></tr><tr><td><strong>Clear formatting</strong></td><td>Remove bold, color, size, and other text styling from the selection.</td></tr><tr><td><strong>Text alignment</strong></td><td>Align left, center, right, or justified.</td></tr><tr><td><strong>Numbered list</strong> / <strong>Bulleted list</strong></td><td>Start or end a list.</td></tr><tr><td><strong>Decrease indent</strong> / <strong>Increase indent</strong></td><td>Change a list or paragraph&#39;s level.</td></tr></tbody></table><p>To place text at the top, middle, or bottom of its box, right-click the box and select <strong>Align text top</strong>, <strong>Align text middle</strong>, or <strong>Align text bottom</strong>.</p><p>How text fits its box is set in the Format options panel. See <a href="/docs/slides/style-and-arrange.html#use-the-format-options-panel">Set text fitting</a>.</p><h2 id="insert-an-image" tabindex="-1">Insert an image <a class="header-anchor" href="#insert-an-image" aria-label="Permalink to &quot;Insert an image&quot;">​</a></h2><ol><li>Click <strong>Insert image</strong> (the picture icon) in the toolbar.</li><li>Choose an image file.</li></ol><p>The image appears centered on the slide at its natural size. A large image is scaled down to fit within 80% of the slide&#39;s width and height. You can also paste an image with <code>⌘+V</code> / <code>Ctrl+V</code>, or drag an image file from your computer onto the slide.</p><p>To swap the picture and keep its position, select it and click <strong>Replace image</strong> in the toolbar. To trim it, see <a href="/docs/slides/style-and-arrange.html#crop-an-image">Crop an image</a>.</p><h2 id="insert-a-shape" tabindex="-1">Insert a shape <a class="header-anchor" href="#insert-a-shape" aria-label="Permalink to &quot;Insert a shape&quot;">​</a></h2><ol><li>Click <strong>Shape</strong> (the shapes icon) in the toolbar.</li><li>Select a shape. The picker has more than 130 shapes in eight groups: Shapes, Block arrows, Banners, Flowchart, Callouts, Equation, Stars, and Action buttons.</li><li>Click the slide to place the shape at its default size, or drag to draw it.</li></ol><p>Hold <code>Shift</code> while you drag to keep the proportions, such as a perfect circle or square. To put text in the shape, select it and start typing.</p><p>Some shapes show a yellow diamond handle when selected. Drag it to change the shape&#39;s form, such as the corner radius of a rounded rectangle or the head of an arrow.</p><p><img src="'+n+'" alt="Shape picker open on the Shapes and Block arrows groups"></p><h2 id="add-a-table" tabindex="-1">Add a table <a class="header-anchor" href="#add-a-table" aria-label="Permalink to &quot;Add a table&quot;">​</a></h2><ol><li>Click <strong>Insert table</strong> (the grid icon) in the toolbar.</li><li>Point at the grid to choose the number of rows and columns, up to 10 × 10.</li><li>Click. The table appears centered on the slide and stays selected.</li></ol><p>Double-click a cell to type in it. Press <code>Tab</code> to move to the next cell and <code>Shift+Tab</code> to go back. <code>Tab</code> in the last cell adds a row.</p><h3 id="add-or-remove-rows-and-columns" tabindex="-1">Add or remove rows and columns <a class="header-anchor" href="#add-or-remove-rows-and-columns" aria-label="Permalink to &quot;Add or remove rows and columns&quot;">​</a></h3><ol><li>Click a cell, or drag across several cells to select a range.</li><li>Right-click the selection.</li><li>Select an item such as <strong>Insert row above</strong>, <strong>Insert column right</strong>, <strong>Delete row</strong>, or <strong>Delete column</strong>. With a range selected, the items match its size, such as <strong>Insert 2 rows below</strong>.</li></ol><p>To join cells, select them, right-click, and select <strong>Merge cells</strong>. <strong>Unmerge cells</strong> splits them again. An insert or delete item is unavailable when it would cut through a merged cell.</p><h3 id="style-cells" tabindex="-1">Style cells <a class="header-anchor" href="#style-cells" aria-label="Permalink to &quot;Style cells&quot;">​</a></h3><p>With cells selected, the toolbar shows <strong>Cell fill</strong>, <strong>Align cell top</strong>, <strong>Align cell middle</strong>, <strong>Align cell bottom</strong>, <strong>Cell borders</strong>, and <strong>Cell padding</strong>.</p><h2 id="connect-shapes" tabindex="-1">Connect shapes <a class="header-anchor" href="#connect-shapes" aria-label="Permalink to &quot;Connect shapes&quot;">​</a></h2><ol><li>Click <strong>Line</strong> (the line icon) in the toolbar and select <strong>Line</strong>, <strong>Arrow</strong>, <strong>Elbow connector</strong>, or <strong>Curved connector</strong>.</li><li>Drag from the first shape to the second. Connection points appear as you near a shape, and the end snaps to one.</li></ol><p>A connected line stays attached when you move either shape. Hold <code>Shift</code> while you drag to snap the angle to 15° steps.</p><p>To label a line, double-click it and type. The label sits at the middle of the line. To change how the line routes, right-click it and select <strong>Straight</strong>, <strong>Elbow</strong>, or <strong>Curved</strong>.</p><h3 id="draw-freehand" tabindex="-1">Draw freehand <a class="header-anchor" href="#draw-freehand" aria-label="Permalink to &quot;Draw freehand&quot;">​</a></h3><ol><li>Click <strong>Line</strong> and select <strong>Scribble</strong>.</li><li>Drag on the slide to draw.</li></ol><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>The phone toolbar changes with what you are doing:</p><ul><li><strong>Nothing selected</strong>: tap <strong>Insert</strong> (the + icon) for a sheet with <strong>Text box</strong>, <strong>Image</strong>, <strong>Shape</strong>, <strong>Line</strong>, and <strong>Table</strong>.</li><li><strong>Object selected</strong>: tap <strong>Format</strong> for its fill, border, and image controls, or the trash icon to delete it.</li><li><strong>Typing</strong>: <strong>Bold</strong>, <strong>Italic</strong>, and <strong>Underline</strong> stay in the bar. Tap <strong>Text formatting</strong> for the font, size, color, alignment, and list controls, and <strong>Done</strong> to finish.</li></ul><p>To type in a text box or shape, double-tap it. An empty placeholder opens for typing with one tap. To open an object&#39;s menu, such as <strong>Duplicate</strong> or <strong>Delete</strong>, touch and hold it. To add a slide, tap <strong>Add slide</strong> at the end of the slide strip below the canvas. It adds a blank slide at the end of the deck. You can&#39;t duplicate, delete, or reorder slides on a phone.</p><p><img src="'+l+'" alt="Insert sheet on a phone with Text box, Image, Shape, Line, and Table"></p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Slide text has no strikethrough or highlight color.</li><li>If two people edit the same text box, table cell, or shape text at once, the person who finishes last overwrites the other&#39;s changes. See <a href="/docs/collaborate/edit-together.html">Edit together</a>.</li><li>Charts come only from imported PowerPoint files and can&#39;t be edited. You can move and resize them.</li><li>Images inside a group can&#39;t be cropped. Ungroup them first.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/slides/style-and-arrange.html">Style and arrange</a> to change fills, borders, and positions.</li><li><a href="/docs/slides/themes-and-layouts.html">Themes and layouts</a> to change a slide&#39;s layout and the deck&#39;s look.</li><li><a href="/docs/slides/keyboard-shortcuts.html">Keyboard shortcuts</a> for every editing shortcut.</li><li><a href="/docs/files/import-export.html">Import and export</a> to bring in a PowerPoint deck.</li></ul>',56)])])}const b=t(r,[["render",i]]);export{m as __pageData,b as default};
